// write path
function saveOrder(order) {
  cache.set("order:" + order.id, order)   // write to Redis only
  enqueueAsyncFlushToDB(order)             // flush to Postgres later, best-effort
  return ACK                               // acknowledge to client now
}
// read path reads order:* from Redis as the authoritative value

