// consumes {key, newValue, version} change events, at-least-once
async function onChange(evt) {
  // write the new value straight into the cache
  await cache.set(evt.key, evt.newValue);
  ack(evt);                       // ack immediately
}

// the producer emits an event on every DB write to the row
